from pathlib import Path
import json,copy,hashlib
R=Path(__file__).resolve().parent;O=R/'output';O.mkdir(exist_ok=True)
W=json.loads((R.parent/'world-depth/source/World_Atlas.json').read_text())
B=json.loads((R.parent/'world-depth/source/Blueprint_Data.json').read_text())
def record(title,**kw):return dict(title=title,**kw)
details=[
dict(daily='At first light an adult rakes mollusks out of river gravel with its whiskers. Its feeding grooves run with the current; a wagon dragged across the bed leaves a different mark. Adults withdraw into deeper bends when traffic grows.',cycle='Eggs adhere to submerged reed roots during the spring rise. Juveniles remain among stems while adults feed nearby. A spawning closure ends after local watchers record dispersal, never because a calendar page turns.',signs='A low silt curl travels upstream before the back breaks the surface. Newly stripped reeds and empty mollusk shells establish presence; ripples alone do not identify a wyrm.',escalation='Feeding -> head lift -> lateral body turn across a disturbed patch -> short defensive rush. Once intruders retreat, it protects the patch instead of pursuing them across dry country.',community='Reedbank watchers compare bank marks with boat crews. Closures hurt ferry income, so the kitchen buys from delayed fishers and the cooperative posts the next inspection time.',scene='A vanished wagon seems to have been taken by a wyrm. Hollis distinguishes feeding grooves from a mechanically pulled tow scar: the animal is real, but the accusation is wrong.',motion='Hold the long body silhouette; animate the whisker fan, gill beat and one continuous tail wave. A rush needs a planned path and splash hold, not a sequence of redesigned bodies.',sounds='Low water displacement, reed scrape, breathy surface exhalation. No speech, roar dialogue or mind link.',palette=['#516B76','#879D9B','#D0C8A4'],rule='Four small paddle limbs, long slate body, reedlike whiskers. Do not add horns, legs for running or stone-boring powers.'),
dict(daily='The rooted colony feeds slowly. Sun and decomposing leaf litter sustain much of its growth; small captured animals provide scarce nutrients. Warm cavities become most tempting during cold wet weather.',cycle='Flowers open in pulses after sustained rain. Seeds establish in undisturbed litter. A severed feeding leaf stays damaged through the scene and cannot regrow during a chase.',signs='Amber cups face the sheltered opening. Sweet resin without the usual leaf-mold smell is the guide warning. The warmth is local, not a valley-wide spell or emotional enchantment.',escalation='Open hollow -> leaf edges draw inward -> fibers brace -> slow closure. The rooted plant cannot chase someone who steps back; a trapped limb still requires help.',community='Canopy guides mark living colonies and teach children to identify them. Ripping out every colony damages banks and feeds a false belief that a cleared path stays safe forever.',scene='During rain, Neri notices that a supposedly helpful shelter has no old footprints or leaf litter. She lets a pupil name the inconsistency instead of turning it into her own lesson.',motion='Keep the root mass registered to the background. Use three designed leaf poses and slow overlap; flowers do not become eyes or a talking mouth.',sounds='Wet fiber tension and leaf rub. No voice, telepathy or deliberate impersonation of a person.',palette=['#546D3F','#BA813B','#D3A454'],rule='Plant anatomy only: fibrous folding leaves and amber cup flowers. A hollow may look mouthlike, but has no jaw or teeth.'),
dict(daily='At cool dawn a drake noses salt beetles from cracks. It warms against stable glass crust, then rests under the rim. Its plates change apparent color with the light rather than changing physical shape.',cycle='Nests occupy bowls beneath old fused crust. Hatchlings use shallow cracks and depend on the same beetle habitat. New windblown glass can hide a nest without moving it.',signs='Parallel six-foot tracks terminate at crust edges. A raised plate fan and a still body warn more clearly than a spectacular reflected flash.',escalation='Freeze -> plate fan -> sideways blocking step -> short bite or shove if crowded. A quiet withdrawal gives it space; vibration tricks are unreliable and may draw it closer.',community='Ossara caravan crews retain bedrock approaches even when a dune shortcut looks faster. Nest closures protect animals and prevent expensive broken loads.',scene='A reflected flash seems to place a suspect at an observatory. Maela finds that a drake plate redirected the light: an image proves light arrived, not how the whole event occurred.',motion='Six limbs stay in three consistent pairs. Lock the plate count and major overlaps for a shot; animate a fan as hinged groups, not melting shards.',sounds='Claws on glass, dry plate clicks and a short hiss. No beams or magical signal reception.',palette=['#B0A68C','#B7D6D9','#D9BD75'],rule='Low six-limbed lizard, translucent overlapping plates; no wings, fire breath or projected energy.'),
dict(daily='A reefback grazes slowly while smaller fish work around its living shell garden. Turning its heavy body changes the water around pilings even when it never notices a boat.',cycle='Adults migrate between feeding grounds; young use warmer shallows. Reef growth takes years. Storm damage remains visible across later scenes until the calendar supports recovery.',signs='A moving line of reef fish, an unfamiliar current against the tide and a rising shell ridge precede a full silhouette. Coral seen through water can be mistaken for a fixed reef.',escalation='Cruise -> slow turn -> sheltering young -> accidental crush risk. It does not become vindictive after a boat touches its shell.',community='Nacre Quay reef tenders close seasonal channels. Fishers and salvagers dispute lost working hours, and the tide council must explain whose income bears the cost.',scene='Toma can secure a valuable crate only by tying to a living shell garden. Letting the crate go saves the reef and costs a real claim, without the animal rewarding him with treasure.',motion='Keep shell profile and major coral clusters fixed. Use a few massive flipper beats and water parallax; do not make the animal bob like a small pet.',sounds='Water pressure, shell scrape and distant low movement. No obedient transport commands.',palette=['#687F79','#C28B64','#5EA6A3'],rule='A 24 m living habitat. It is neither a convenient mount nor an island that instantly grows new buildings.'),
dict(daily='A manta glides along pressure fronts through airborne spore columns. Its fin ribbons stream differently before a turn. Luminous throat spots remain anatomical features rather than warning lights for humans.',cycle='Seasonal spore blooms draw loose feeding groups. Weather moves the column; the creatures follow it. They cannot create a storm to arrive on cue.',signs='Ribbons draw inward before a banking turn; pale spore haze becomes visible against darker clouds. Clear blue sky does not guarantee an empty flight lane.',escalation='Glide -> bank -> feed through column -> turbulence wake. Collision is the danger. A crew cannot negotiate with the animal or count on it avoiding a sail.',community='Aurel Quay dispatchers publish observed feeding lanes alongside weather and loading limits. Delay means feeding passengers and paying stranded crews, not simply declaring safety virtuous.',scene='Eri rejects a clear-looking launch lane. A rival claims she is protecting her own business; she shares observations and opens the record to another crew’s correction.',motion='A broad rigid wing root supports flexible tips. Animate one banking action with a coherent body axis; ribbons lag the turn. No constant full-body wobble.',sounds='Wind shear and sail buffeting; throat resonance is animal sound, never a storm-summoning song.',palette=['#9C9C8A','#D3A857','#F1D98C'],rule='22 m span, 12 m length. Weather-bound glider, not a magic flying vehicle.'),
dict(daily='In cold ice pockets this mothlike predator waits with folded wings. Resonant throat membranes reproduce fragments it recently heard. The lure is behavior, not knowledge of a listener’s grief.',cycle='Young shelter in cold crevices. Adults range farther when natural prey becomes scarce. Warm civic caverns limit their activity; they do not comfortably stalk the town indoors.',signs='A repeated syllable has the same damaged edge each time. Powder disturbed by wing wash and a pale membrane flicker can confirm an animal; an echo alone cannot.',escalation='Folded wait -> fragment repetition -> short glide toward prey -> retreat from warmth. It may repeat a voice outside the context in which it heard it.',community='Hushvale travelers agree a visible check signal before separating. Archive interpreters distinguish animal mimicry from echo-ice playback and from living witnesses.',scene='Ysolde hears a familiar phrase and identifies the mechanism correctly. The emotional challenge remains: admitting what she wanted the voice to mean.',motion='Design folded and open wing silhouettes with the same landmarks. Throat pulses accompany copied fragments. No ghostly face morph or floating human apparition.',sounds='Only fragments acquired in the current encounter or documented recent exposure. Never reveal secrets the creature could not have heard.',palette=['#DCE5E5','#98ACBE','#C1AEBB'],rule='Predatory animal, not a spirit or resurrected person. Five-metre wing span; heat weakens the membranes.'),
dict(daily='An ashmaw follows thermal gradients through loose mineral soil. It scavenges organic kiln waste and catches small ground animals; the old industrial waste stream made settlement edges reliable feeding places.',cycle='Young occupy sheltered warm soil, away from fresh vents. Changing a waste route can redirect adults toward a neighboring terrace. Nest movement is not a harmless off-screen cleanup.',signs='Fresh shallow ridges converge toward a heat source. Charcoal plates may be visible before the orange mouth lining appears. Glowing lining does not mean its body is molten.',escalation='Forage -> stop and taste air -> armor hunch -> brief charge or dig. Cool stable rock interrupts digging; liquid lava and extreme heat can kill it.',community='Kettle Crown crews cool and contain waste before transfer. Cinder residents insist that a city’s cleanup cannot simply export animal hazards to their homes.',scene='Kesh discovers that the cheapest new disposal route would protect a wealthy kiln district by endangering a worker terrace. The correction costs money and public pride.',motion='Use a heavy low center of mass, short digging strokes and rigid overlapping armor groups. Do not dissolve the creature into stone or flames.',sounds='Plate rasp, gravel churn and close breath. Mouth glow remains subtle, no flame attack.',palette=['#343936','#705D43','#D58B37'],rule='Armored burrower and scavenging predator; no lava swimming or unlimited heat resistance.'),
dict(daily='Bell-eels hunt vibrations in deep channels. Mineral-rimmed chambers resonate as the flexible body moves. Brightness may reveal position but does not frighten them away.',cycle='Nesting occurs in quiet rock pockets when local water conditions permit. Lumen Tide observers record the season by the channel, not by a surface calendar.',signs='A hull tap answered by a low water-borne ring suggests investigation. Suspended silt and chamber glints help locate movement; sound can travel from elsewhere.',escalation='Distant orienting -> parallel follow -> close investigation -> strike at a strong local stimulus. A quiet boat is less conspicuous, not magically invisible.',community='Navigators teach quiet handling and protect nesting charts. Rescue partners receive the route facts they need without automatic access to every protected pocket.',scene='Namu shares a narrow rescue chart and accepts a visitor’s correction to a sounding. Trust grows through usable, bounded information rather than surrender of the whole archive.',motion='Lock chamber number and spacing for each animal design; bend the body continuously. Do not generate disconnected glowing beads or growing extra fins.',sounds='Low resonances conducted through water and occasional surface ripples. No sonar that reads minds or understands messages.',palette=['#829DA3','#B9CECA','#D7B16D'],rule='Blind channel hunter; seven-metre representative length, no light-repulsion shortcut and no tunnel to the Burrow.'),
dict(daily='A packbeast grazes salt grass, chews slowly and folds its cooling sail in narrow shade. Six broad padded feet spread weight. Caravans plan feed, rest and water as actual cargo costs.',cycle='Herds remain near oasis margins during vulnerable young-rearing periods. Training builds tolerance for harness and routine; it does not remove fear or fatigue.',signs='A lowered head and widely planted front pair often precede refusal. A damaged harness can cause the same behavior as unstable crust, so handlers inspect both.',escalation='Slows -> stops -> turns head toward handler -> backs away under pressure. It is not stubborn comic machinery that moves when struck.',community='Ossara handlers can stop a departure without the merchant’s consent. Their reputation rests on reading animals accurately, not claiming they are infallible.',scene='An impatient courier blames the lead animal. Maela first checks the harness, then discovers hollow glass under the shortcut; neither explanation is assumed in advance.',motion='Maintain six contact points with a readable alternating gait. Fold the sail along consistent ribs. Cargo and harness must remain attached to the same landmarks.',sounds='Breath, chewing and low contact calls. No speaking role or transformation into a warrior.',palette=['#B39A70','#D3BF8F','#D3A363'],rule='Domestic herbivore with six legs, broad padded feet and foldable sail. Needs water and rest; never an inexhaustible engine.'),
dict(daily='At dusk adults pollinate night flowers. Their amber abdomens brighten with temperature and mating behavior, while leaflike wing cases conceal them in daylight.',cycle='Larvae develop in decaying plant matter. Gardeners leave a small litter patch instead of polishing every surface bare. A cold spell dims an entire colony without a conspiracy.',signs='Pollen on leaf edges and feeding nicks connect insects to a living garden. Brightness alone is not a weather forecast or a magical danger detector.',escalation='Rest -> antenna sweep -> wing-case lift -> short flight. Handling and confinement can suppress the light.',community='Willowmere observation gardens invite visitors to watch without collecting jars of insects. Ordinary lamps still light the path home.',scene='Neri’s planned glowing lesson goes dark. The class discovers the cold litter bed and measures what actually changed; she lets the unexpected result stand.',motion='Keep six legs and two wing cases. Use a held body, antenna action and a short flight loop. Amber pulse does not alter the insect’s outline.',sounds='Tiny wing buzz and leaf contact. Do not amplify it into a companion voice.',palette=['#467247','#A4B86A','#E9B74F'],rule='Palm-sized pollinator, 12 cm representative length. Not a reusable battery, magical beacon or proof of moral goodness.'),
dict(daily='A deep sail snail grazes floating fungal mats with slow rhythmic mouth movements. Buoyancy comes from its ridged shell; sensory fronds track nearby water and surfaces.',cycle='Small juveniles shelter beneath healthy mats. Live shell damage reduces buoyancy and exposes tissue. Empty shells enter the material economy only after natural death.',signs='Fresh curved grazing edges show an occupied mat. A drifting shell is not necessarily empty: tenders check for retracted tissue without tearing it free.',escalation='Graze -> retract fronds -> withdraw -> drift with current. It does not consent to being handled simply because it cannot flee quickly.',community='Lumen Tide craftspeople mark the provenance of naturally empty shells and gather shed mineral fragments. Fast tourist demand can make a truthful supply chain valuable.',scene='A beautiful instrument comes with an impossible harvest date. Namu must question a respected maker without condemning the whole craft tradition.',motion='Shell remains rigid; foot and fronds move slowly beneath it. Do not turn a living shell into a detachable hat.',sounds='Soft grazing rasp and tiny shell contacts. Instrument tones belong to empty shells used by makers, not animal speech.',palette=['#D0D9D1','#9FBDBD','#D6BD8A'],rule='Living shells cannot be removed without killing the animal. No instant regrowth or endless shell farming.'),
dict(daily='A ridge ram browses shelf vegetation and rests beside warm stone. Herd movement follows stable ledges rather than the shortest line across a mountain drawing.',cycle='Calves slow the group and make narrow passing places sensitive. Winter snow can cover yesterday’s widening point, requiring a fresh route inspection.',signs='Split hoof tracks converge at a ledge; torn grass and fresh droppings show recent use. A squared stance with calves behind is a boundary warning.',escalation='Watch -> block -> stamp -> short charge if trapped. Leaving an open retreat is more useful than proving dominance.',community='Frostspine guides maintain marked widening points. Travelers build time for a herd crossing into the journey rather than treating every delay as an antagonist.',scene='An urgent messenger must wait while a calf finds its footing. The cost of delay is real, but pushing past would turn one crisis into two.',motion='Broad spiral horns keep orientation; weight transfers through four legs. Use planted poses and one decisive stamp, not constant jittering fur.',sounds='Hooves, breath and ordinary herd calls. No prophetic animal voice.',palette=['#758996','#B1BCC0','#A88F68'],rule='Mountain herbivore, not innately hostile. Calves, terrain and fatigue govern behavior; horns never become magical weapons.')]
cards=[]
for i,(base,detail) in enumerate(zip(W['creatures'],details)):
 cards.append(dict(id=base['id'],name=base['name'],baseline=copy.deepcopy(base),**detail,art=dict(file='ART-03_Bestiary.png',column=i%4,row=i//4,grid=[4,3]),canon_status='Additive ecology and production guidance; proposed scene remains unadopted.'))
regions=[
('REG-01','Water makes the timetable','River plants and algae -> mollusks and ordinary fish -> flood-wyrms; bank insects feed birds. Reed beds also slow erosion.','Spring rise brings spawning restrictions; dry late-season banks change ferry landings. Inspections, not dates alone, reopen a ford.','Reedbank boat crews and kitchens absorb delay; Millmere depends on maintained sluices; the Burrow stores staples and trades for varied food.','A shorter crossing saves a day but destroys a reed patch that protects the next flood season.'),
('REG-02','A forest that moves slowly','Night flowers -> moss lantern beetles; litter supports decomposers and small animals; mawroot takes some of those animals. Moving crowns change shade and moisture.','Wet-season crown motion changes bridge alignment. Flowering pulses follow local moisture; a cool week can dim beetles during a festival.','Crownrest bridge crews hold crossing authority; Willowmere growers keep dated seed and path records. Seasonal changes need work, not prophecy.','A crowd wants a festival bridge open after the tree has shifted; a local guide must disappoint friends.'),
('REG-03','Shade, water and patient loads','Salt grass -> sailfin packbeasts; dry plant litter -> salt beetles -> glassback drakes. Wells and rain-fed margins concentrate life.','Cool light favors travel; storms move loose glass over stable crust. Local wells refill unevenly, and a viable well never means unlimited growth.','Ossara well assemblies negotiate demand; caravan handlers count animal water and feed as part of every commercial promise.','A merchant’s genuine shortage and a fabricated debt occur together; resolving fraud does not end drought.'),
('REG-04','The living channel','Sunlit marine growth -> small grazers and fish; reefbacks support moving reef communities. Tidal exchange connects habitats and alters access.','Reefback passage and tidal windows are separate schedules. A low tide does not cancel a migration closure.','Nacre Quay tenders, fishers and salvage families share the cost of closures. Descendant claims remain relevant when an object becomes exposed.','A rescue route opens just as a profitable archive window closes; the town must choose what it can afford to lose.'),
('REG-05','The weather has passengers','Terrace growth and drifting fungal spores support small airborne life and storm mantas. Imported staples remain essential to Aurel Quay.','Spore fronts attract mantas; wind and liftstone load budgets separately govern departures. No single green indicator grants a launch.','Dock crews shelter delayed travelers; sailwrights and gardens keep the port alive between glamorous flights.','Rescue is necessary, but taking everyone at once exceeds the craft’s load budget.'),
('REG-06','Warmth is a place','Ridge plants and lichens support rams; small cave animals support choirwraiths. Geothermal margins create local refuges within a much colder region.','Snow alters ledges; cold permits predator activity farther from ice pockets. Warm refuge capacity and fuel deliveries constrain a journey.','Hushvale guides and archive readers compare physical conditions with inherited warnings; neither alone settles a route.','A forged prohibition is exposed without making the real resonance closure safe.'),
('REG-07','Waste belongs to someone','Heat-grown gardens feed residents; insects and organic industrial waste support ashmaws. Mineral heat enables habitat but is not edible fuel by itself.','Cooling cycles and vent changes shift animal routes. A new disposal practice can matter more than a seasonal migration.','Kettle Crown’s prosperity and Cinder’s losses are connected by transport decisions. Wildlife mitigation cannot be dumped onto poorer terraces.','A clean-looking factory yard has sent both its cost and its predators downhill.'),
('REG-08','An ocean below the map','Mineral-fed microbial production and cultivated fungi support mats and grazers, including deep sail snails; channel prey supports bell-eels. Surface grain trade supplements, not founds, deep society.','Local water levels, pressure and air quality govern passage. Nesting windows are recorded by channel, with no promise that a surface season matches.','Lumen Tide has its own six-century history, law and navigation expertise. Visitors receive usable route information while restricted nesting charts remain protected.','A rescue partner needs a corrected depth, not ownership of every sheltered shore.')]
ecology=[dict(id=a,title=b,food_web=c,season=d,community=e,conflict=f) for a,b,c,d,e,f in regions]
rules=[
record('Citizens, companions and wildlife',text='Anthropomorphic citizens and mechanical persons have agency and moral responsibility. Snow White and the twelve wild/domestic creature species are animals. An animal’s danger is behavior and circumstance, not proof that its species is evil. Brakka and Nix choose their actions; a flood-wyrm does not choose a political side.'),
record('Four conditions, not a permanent safe color',text='Every exterior scene records NORMAL, RESTRICTED, CLOSED or EMERGENCY conditions, the observation time and who made the call. Normal means the listed route is available under its stated assumptions; it never erases weather, tide, heat or fatigue. A closure does not magically disappear when heroes arrive.'),
record('Ordinary Burrow ecology',text='The established surface neighborhoods, underground homes and service level keep their existing geometry. Stored grain, legumes, roots, fruit, cultivated fungi and regional imports support meals. Ventilation, clean water and separated waste work remain civic labor; no new wildlife tunnel, deep-sea entrance or predator nest is added under the defense line.'),
record('Local calendars',text='This volume adds observation-based seasonal cues, not a new universal calendar. A wet canopy season, river rise and deep-water nesting period can overlap differently in different years. Production must record elapsed travel and local conditions before tying two events together.'),
record('Evidence has limits',text='Tracks establish passage, not motive. A copied sound is not testimony. Reflected light omits context. A real animal hazard can coexist with a theft, a good-faith mistake or a false rumor; no creature is a universal answer to a mystery.'),
record('Replicable staging',text='Text and JSON specify anatomy, dimensions, behavior and limits. Existing bestiary art is retained for appearance; its subjects are not drawn to common scale. New environment art is atmosphere. Measured SVG plans control the exact set, while poses and routes are selected explicitly for each shot.'),
record('Pilot stays inside',text='No creature encounter or exterior cutaway is inserted into episode one. The pilot’s warmth, bounded D17 discrepancy and unrelated resin clue remain unchanged. Wildlife stories become available only after the audience has met the Burrow.'),
record('New story status',text='The two stories and all encounter seeds are complete authored options. They are not dated events until adopted into the episode ledger. Core history, relationships, voices and existing season arcs remain controlling.')]
D=dict(edition='3.3.0',date='2026-10-21',title='The Wilds Between',base_commit='ab09a910dce920270ec8f1ec802bed6e6b722c12',moral='Care begins with paying attention; courage includes accepting a limit and carrying its cost.',rules=rules,creatures=cards,regional_ecology=ecology,source_authority=['World Atlas 3.0','Living Places 3.1','The Cost of Control 3.2'],pilot_exterior_scenes=0)
(O/'Wilds_Bible.json').write_text(json.dumps(D,indent=2,ensure_ascii=False))
for c in cards:(O/'cards'/f"{c['id']}.json").write_text(json.dumps(c,indent=2,ensure_ascii=False))
print('Twelve creature cards and eight regional ecologies authored.')
